func doCooldownEffect():
	character().changeBuffProtectStacks(protectedBuffs)
	heal()
	if invuCharges > 0 and character().isVulnerable() and checkMana(manaCost):
		invuCharges -= 1
		setState(CrownState.Active, true)
		var invuDur = getP_m("dur_invu")
		var event = character().makeInvulnerable(invuDur, self)
		buffTimer.start(invuDur)
		useMana(manaCost, event)
		Util.createPulse(activationPulse, self, global_position)

func buffEnded():
	if invuCharges > 0:
		setState(CrownState.Inactive, true)
	else:
		setState(CrownState.Used, true)

func onStateChanged(_crownState):
	if _crownState == CrownState.Inactive:
		activationParticles.deactivate()
		light.self_modulate = Color.white
		light.show()

	elif _crownState == CrownState.Active:
		activationParticles.activate()
		light.self_modulate = Color(1.3, 1.3, 1.3, 1)
		light.show()

	else:
		activationParticles.deactivate()
		light.hide()

func activate():
	timer.stop()


	show()

	if one_shot:
		restart()
		startTimer()
	else:
		emitting = true

func deactivate():
	if visible:
		emitting = false
		startTimer()

func makeInvulnerable(invuDur, item, triggerEvent = null):
	invulnerabilityItem = item

	if not invulnerable:
		invulnerabilityTimer.start(invuDur)
		invulnerable = true
		playInvulnerableAnimation(true)
		Sound.playSound(invuSound, 4, Util.randPitch(0.1))
	else:
		Util.changeTimer(invulnerabilityTimer, invuDur)

	var event = Game.combatLog.createEvent_InvulnerableStart(item, invuDur, playerId, triggerEvent)
	EventBus.emitEvent(self, "character_invulnerable_start", event, [event])
	Game.combatLog.snapshotCharacterStat(self, Stat.Invulnerable, false, event)
	return event

func invulnerabilityEnded():
	invulnerable = false
	var event = Game.combatLog.createEvent_InvulnerableEnd(invulnerabilityItem, playerId)
	EventBus.emitEvent(self, "character_invulnerable_end", event, [event])
	Game.combatLog.snapshotCharacterStat(self, Stat.Invulnerable, false, event)
	playInvulnerableAnimation(false)

func activateItems(items):


	emit_signal("combat_start")
	combatTimer.start()

	PLAYER.combatStart()
	OPPONENT.combatStart()

	for item in items:
		item.preCombatStart()

	for item in items:
		item.combatStart()

	for item in items:
		item.postCombatStart()

func combatEndDeferred():
	emit_signal("combat_end", roundResults[curRound - 1])

	EventBus.disconnectAll()
	PLAYER.combatEnd()
	OPPONENT.combatEnd()
	combatTimer.combatEnd()

	if roundResults[curRound - 1] == RoundResult.Win:
		OPPONENT.setCurrentHealth(0)
		PLAYER.setCurrentHealth(max(1, PLAYER.getCurrentHealth()))
	else:
		PLAYER.setCurrentHealth(0)
		OPPONENT.setCurrentHealth(max(1, OPPONENT.getCurrentHealth()))

	for item in PLAYER.INVENTORY.getItems() + OPPONENT.INVENTORY.getItems():
		item.combatEnd()

	ropeSpeedups.clear()
	cubeAdvanced.clear()
	sandbagActive = false

	curRound += 1
	if curMode != Mode.History:
		emit_signal("round_result")


	if SteamHelper.canUnlock():
		if getLastRoundResult() == RoundResult.Win:
			if combatTimer.combatTime < 3:
				SteamHelper.unlockAchievement("FastBattle")
			elif combatTimer.combatTime >= 45:
				SteamHelper.unlockAchievement("SlowBattle")

			var noWeapon = true
			for item in PLAYER.INVENTORY.getItems():
				if item.hasType(Item.Type.Weapon):
					noWeapon = false
					break
			if noWeapon:
				SteamHelper.unlockAchievement("NoWeapon")

			if PLAYER.getRelativeHealth() == 1:
				SteamHelper.unlockAchievement("FullHealth")
			elif PLAYER.getCurrentHealth() == 1:
				SteamHelper.unlockAchievement("1Health")

			checkForInventoryAchievements()

		if PLAYER.getBuffStacks() >= 100:
			SteamHelper.unlockAchievement("ManyBuffs")
		elif OPPONENT.getDebuffStacks() >= 100:
			SteamHelper.unlockAchievement("ManyDebuffs")

		if numTimesOutOfStamina >= 10:
			SteamHelper.unlockAchievement("OutOfStamina")



	Sound.fadeOutBGM(1)

	if runOver():
		if curMode == Mode.Lobbies:
			endRun_lobby()
		else:
			endRun(true, true)

func _physics_process(delta):

	if not get_tree().paused:
		frameCounter += 1
		time += delta

	var curMousePos = getMousePosInWindow()
	mouseVelocity = (curMousePos - lastMousePos)
	lastMousePos = curMousePos
